CREATE TABLE merchants (id int PRIMARY KEY, name text, country text);
INSERT INTO merchants
  SELECT g, 'merchant-' || g, (ARRAY['NL','DE','FR','ES','IT'])[1 + g % 5]
  FROM generate_series(1, 1000) g;
CREATE TABLE payments (id bigint PRIMARY KEY, merchant_id int, amount_cents bigint);
INSERT INTO payments
  SELECT g, 1 + (g * 7919) % 1000, (g * 104729) % 100000
  FROM generate_series(1, 100000::bigint) g;
VACUUM ANALYZE merchants, payments;
SET max_parallel_workers_per_gather = 0;

EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT id, amount_cents FROM payments WHERE amount_cents > 90000 LIMIT 5;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT id, amount_cents FROM payments WHERE amount_cents > 90000;

SET max_parallel_workers_per_gather = 0;
SET enable_hashjoin = off;
SET enable_memoize = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT p.id, m.name FROM payments p JOIN merchants m ON m.id = p.merchant_id
  WHERE p.id <= 10;

SET enable_mergejoin = off;
SET enable_indexscan = off;
SET enable_bitmapscan = off;
SET enable_material = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF)
  SELECT m.country, sum(p.amount_cents)
  FROM payments p JOIN merchants m ON m.id = p.merchant_id GROUP BY m.country;
RESET ALL;

SET max_parallel_workers_per_gather = 0;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF)
  SELECT m.country, sum(p.amount_cents)
  FROM payments p JOIN merchants m ON m.id = p.merchant_id GROUP BY m.country;

SET enable_hashjoin = off;
SET enable_nestloop = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF)
  SELECT m.country, sum(p.amount_cents)
  FROM payments p JOIN merchants m ON m.id = p.merchant_id GROUP BY m.country;
RESET enable_hashjoin;
RESET enable_nestloop;

CREATE TABLE refunds AS
  SELECT g AS id, g * 3 AS payment_id, 500 AS amount_cents FROM generate_series(1, 30000::bigint) g;
VACUUM ANALYZE refunds;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF)
  SELECT sum(p.amount_cents - r.amount_cents) FROM payments p JOIN refunds r ON r.payment_id = p.id;
SET work_mem = '256kB';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, BUFFERS OFF)
  SELECT sum(p.amount_cents - r.amount_cents) FROM payments p JOIN refunds r ON r.payment_id = p.id;
RESET ALL;

SET max_parallel_workers_per_gather = 0;
SELECT sum(amount_cents) FROM payments WHERE amount_cents > 9000;   -- warms the cache

SET jit = off;
EXPLAIN (ANALYZE, BUFFERS OFF) SELECT sum(amount_cents) FROM payments WHERE amount_cents > 9000;

SET jit = on;
SET jit_above_cost = 0;             -- compile even this cheap query
EXPLAIN (ANALYZE, BUFFERS OFF) SELECT sum(amount_cents) FROM payments WHERE amount_cents > 9000;

SET jit_optimize_above_cost = 0;    -- and optimize and inline it, as for an expensive one
SET jit_inline_above_cost = 0;
EXPLAIN (ANALYZE, BUFFERS OFF) SELECT sum(amount_cents) FROM payments WHERE amount_cents > 9000;
RESET ALL;

