class Filter(child: Operator, private val predicate: (Row) -> Boolean) : Unary(child) {
    override fun next(): Row? {
        while (true) {
            val row = child.next() ?: return null   // a call per row
            if (predicate(row)) return row           // another call per row
        }
    }
}

