        val b = child.nextBatch() ?: return null     // a call per batch
        val c = b.columns[column]
        val selected = IntArray(b.size)
        var n = 0
        for (i in 0 until b.size) {                    // a tight loop, no calls
            if (c[i] > greaterThan) selected[n++] = i
        }
        if (n == 0) continue
        return Batch(b.columns.map { col -> LongArray(n) { col[selected[it]] } }, n)
    }
}

