private var outer: Row? = null

override fun open() {
    left.open()
    outer = left.next()
    if (outer != null) right.open()
}

override fun next(): Row? {
    while (true) {
        val l = outer ?: return null              // left side used up: done
        val r = right.next()
        if (r == null) {                          // right side used up for this left row
            outer = left.next() ?: return null
            right.close()                         // rescan it for the next left row
            right.open()
            continue
        }
        val k = l[leftKey]
        if (k != null && k == r[rightKey]) return l + r
    }
}

// 100 left rows: the right side is opened 100 times (once in open, then 99 rescans),
// and it produces 100 x |right| rows in total.
